// Create a connector and optionally link it to a project. Use `type` with complete provider data, or use `service` with `connectionMethod` so Connect can supply the type, endpoints, templates, and defaults.
//
// Parameters:
//
//	data: Provider configuration for the selected connector type or connection
//	method.
//	teamId: The team ID that scopes the request. Do not send it with slug. If
//	both are omitted, Vercel uses the team associated with the token or the
//	authenticated user's default team. The request returns 401 if no team can be
//	selected.
//	slug: The team slug that scopes the request. Do not send it with teamId. If
//	both are omitted, Vercel uses the team associated with the token or the
//	authenticated user's default team. The request returns 401 if no team can be
//	selected.
//	icon: SHA-1 digest of a PNG or JPEG icon that is at least 640 by 640 pixels.
//	This field does not accept a URL or image bytes. First compute the digest
//	and upload the raw image with [POST
//	/v2/files](https://vercel.com/docs/rest-api/deployments/upload-deployment-fi
//	les). Send `Content-Length` and the same 40-character digest in
//	`x-vercel-digest`. Then set `icon` to that digest. ```js import { createHash
//	} from 'node:crypto'; import { readFile } from 'node:fs/promises'; const
//	VERCEL_TOKEN = process.env.VERCEL_TOKEN; const connectorId = 'scl_...';
//	const bytes = await readFile('icon.png'); const digest =
//	createHash('sha1').update(bytes).digest('hex'); await
//	fetch('https://api.vercel.com/v2/files', { method: 'POST', headers: {
//	Authorization: `Bearer ${VERCEL_TOKEN}`, 'Content-Type':
//	'application/octet-stream', 'Content-Length': String(bytes.length),
//	'x-vercel-digest': digest, }, body: bytes, }); await
//	fetch(`https://api.vercel.com/v2/connect/connectors/${connectorId}`, {
//	method: 'PATCH', headers: { Authorization: `Bearer ${VERCEL_TOKEN}`,
//	'Content-Type': 'application/json', }, body: JSON.stringify({ icon: digest
//	}), }); ```
//	backgroundColor: Branding background color (6-digit hex, for example
//	accentColor: Branding accent color (6-digit hex, for example
//	type_: Connector implementation type for full configuration. Known types:
//	api-key, discord, github, linear, linq, microsoft-entra, oauth, photon,
//	salesforce, sendblue, slack, snowflake, snowflake-wif. Optional when service
//	and connectionMethod select the type.
//	service: Service slug or URL for which the connector is used. Required when
//	connectionMethod is set. Service alone does not enable preset configuration.
//	connectionMethod: Connection method slug of the service. Use it with service
//	to select preset configuration.
//	params: Values for the selected connection method's template fields.
//	Requires connectionMethod.
//	target: Which of the service's targets this connector is for. Requires
//	\"connectionMethod\" and must be one that method serves. Optional.
//	uid: Optional team-scoped unique identifier for the connector. If omitted or
//	empty, Connect generates a value.
//	name: Connector name. The value is trimmed and cannot contain control
//	characters. If omitted or empty, the project name is used. A name or
//	projectId is required. API key connectors require name.
//	projectId: Project to connect during creation. If environments is omitted,
//	the connection uses development, preview, and production.
//	environments: Environments for the project connection. Requires projectId.
//	Use one or more built-in environment names or stable custom environment IDs
//	that belong to the project. Duplicate values are accepted and removed.
//	triggers: Whether the triggers are enabled for this connector.
//	triggerType: Trigger driver type. Resolved automatically from the known
//	service connection method when not provided. Only set when using the newly
//	decoupled triggers resolution flow.
//	triggerVerificationInput: Plaintext verification inputs, validated by the
//	trigger driver and encrypted into stored triggerData. An empty object makes
//	no changes.
//	triggerRegistrationInput: Additional registration inputs, validated by the
//	trigger driver. Requires triggers: true. Shared verification credentials are
//	read from triggerData.
//	triggerDestination: Initial trigger destination. Requires triggers to be
//	enabled and a projectId here or at the top level. Connector responses expose
//	the resulting set as triggerDestinations. Replace the complete set with
//	PATCH /v1/connect/connectors/{connector}/trigger-destinations.
//	events: Default trigger events for this connector.
func (sdk *ConnectNamespace) CreateConnector(ctx context.Context, requestParams CreateConnectorParams, opts ...RequestOption) (*ConnectConnectorCreateResult, error) {
	return CreateConnector(ctx, sdk.config, requestParams, opts...)
}

// UpdateConnector updates connector configuration, trigger settings, or display details and returns any provider-side follow-up signals. Supply only the fields you want to change, and handle any reconsent, reinstall, or service synchronization information in the response.
//
// Update a connector and return the connector with any service-side update signals that the caller must handle.
//
// Parameters:
//
//	connector: Stable connector ID or URL-encoded team-scoped UID. Examples:
//	`scl_abc123` or `slack%2Fmy-bot`.
//	teamId: The team ID that scopes the request. Do not send it with slug. If
//	both are omitted, Vercel uses the team associated with the token or the
//	authenticated user's default team. The request returns 401 if no team can be
//	selected.
//	slug: The team slug that scopes the request. Do not send it with teamId. If
//	both are omitted, Vercel uses the team associated with the token or the
//	authenticated user's default team. The request returns 401 if no team can be
//	selected.
//	triggers: Whether the triggers are enabled for this connector.
//	triggerVerificationInput: Plaintext verification inputs, validated by the
//	trigger driver and encrypted into stored triggerData. An empty object makes
//	no changes.
//	triggerRegistrationInput: Additional registration inputs, validated by the
//	trigger driver. Requires triggers: true. Shared verification credentials are
//	read from triggerData.
//	events: Default trigger events for this connector.
//	data: Provider configuration fields to update.
//	icon: SHA-1 digest of a PNG or JPEG icon that is at least 640 by 640 pixels.
//	This field does not accept a URL or image bytes. First compute the digest
//	and upload the raw image with [POST
//	/v2/files](https://vercel.com/docs/rest-api/deployments/upload-deployment-fi
//	les). Send `Content-Length` and the same 40-character digest in
//	`x-vercel-digest`. Then set `icon` to that digest. ```js import { createHash
//	} from 'node:crypto'; import { readFile } from 'node:fs/promises'; const
//	VERCEL_TOKEN = process.env.VERCEL_TOKEN; const connectorId = 'scl_...';
//	const bytes = await readFile('icon.png'); const digest =
//	createHash('sha1').update(bytes).digest('hex'); await
//	fetch('https://api.vercel.com/v2/files', { method: 'POST', headers: {
//	Authorization: `Bearer ${VERCEL_TOKEN}`, 'Content-Type':
//	'application/octet-stream', 'Content-Length': String(bytes.length),
//	'x-vercel-digest': digest, }, body: bytes, }); await
//	fetch(`https://api.vercel.com/v2/connect/connectors/${connectorId}`, {
//	method: 'PATCH', headers: { Authorization: `Bearer ${VERCEL_TOKEN}`,
//	'Content-Type': 'application/json', }, body: JSON.stringify({ icon: digest
//	}), }); ```
//	uid: Full team-scoped UID, such as `slack/my-bot`. It cannot contain
//	whitespace, `%`, `#`, control characters, or Vercel-owned namespaces.
//	Changing it breaks callers that use the old UID. The stable connector ID
//	does not change.
//	name: Display name for the connector. It is trimmed and cannot be empty or
//	contain control characters.
func (sdk *ConnectNamespace) UpdateConnector(ctx context.Context, params UpdateConnectorParams, opts ...RequestOption) (*ConnectConnectorUpdateResult, error) {
	return UpdateConnector(ctx, sdk.config, params, opts...)
}

// ReplaceConnectorTriggerDestinations replaces the complete set of trigger destinations for a connector. Submit all destinations you want to retain in `destinations`; an empty array removes every destination, and the replacement can contain at most three entries.
//
// Replace the full set of destinations that receive trigger requests for a connector.
//
// Parameters:
//
//	connector: Stable connector ID or URL-encoded team-scoped UID. Examples:
//	`scl_abc123` or `slack%2Fmy-bot`.
//	destinations: Complete replacement set of trigger destinations. An empty
//	array removes all destinations. Connector get and list responses expose the
//	saved set as triggerDestinations.
//	teamId: The team ID that scopes the request. Do not send it with slug. If
//	both are omitted, Vercel uses the team associated with the token or the
//	authenticated user's default team. The request returns 401 if no team can be
//	selected.
//	slug: The team slug that scopes the request. Do not send it with teamId. If
//	both are omitted, Vercel uses the team associated with the token or the
//	authenticated user's default team. The request returns 401 if no team can be
//	selected.
func (sdk *ConnectNamespace) ReplaceConnectorTriggerDestinations(ctx context.Context, params ReplaceConnectorTriggerDestinationsParams, opts ...RequestOption) (*ConnectConnector, error) {
	return ReplaceConnectorTriggerDestinations(ctx, sdk.config, params, opts...)
}
